import { useState } from 'react';
import { MetaCard } from '../components/MetaCard';
import { MetaForm } from '../components/MetaForm';
import { Botao, Cartao, EstadoVazio, TituloPagina } from '../components/ui';
import { hojeISO } from '../domain/date';
import { criarMeta, ordenarMetas } from '../domain/metas';
import { useEstado, useStore } from '../state/store';
import './MetasPage.css';

export function MetasPage() {
  const store = useStore();
  const estado = useEstado();
  const [criando, setCriando] = useState(false);
  const [mostrarArquivadas, setMostrarArquivadas] = useState(false);
  const hoje = hojeISO();

  const arquivadas = estado.metas.filter((m) => m.status === 'arquivada');
  const visiveis = ordenarMetas(estado.metas.filter((m) => mostrarArquivadas || m.status !== 'arquivada'));

  return (
    <div>
      <TituloPagina acoes={!criando ? <Botao onClick={() => setCriando(true)}>Nova meta</Botao> : undefined}>Metas</TituloPagina>
      <div className="metas-pagina">
        {criando ? (
          <Cartao titulo="Nova meta">
            <MetaForm
              onCancelar={() => setCriando(false)}
              onSalvar={(dados) => {
                const r = store.aplicar((s) => criarMeta(s, dados, hoje));
                if (r.ok) setCriando(false);
                return r;
              }}
            />
          </Cartao>
        ) : null}

        {arquivadas.length > 0 ? (
          <label className="metas-filtro-arquivadas">
            <input type="checkbox" checked={mostrarArquivadas} onChange={(e) => setMostrarArquivadas(e.target.checked)} />
            Mostrar metas arquivadas ({arquivadas.length})
          </label>
        ) : null}

        {visiveis.length === 0 && !criando ? (
          <EstadoVazio titulo="Nenhuma meta ainda" acao={<Botao onClick={() => setCriando(true)}>Crie sua primeira meta</Botao>}>
            Defina um objetivo de poupança, como uma reserva de emergência ou uma viagem, e acompanhe seus aportes.
          </EstadoVazio>
        ) : null}

        {visiveis.map((m) => (
          <MetaCard key={m.id} meta={m} hoje={hoje} />
        ))}
      </div>
    </div>
  );
}
import { useState } from 'react';
import { AlocacaoCarteira } from '../components/investimentos/AlocacaoCarteira';
import { AtivoCard } from '../components/investimentos/AtivoCard';
import { AtivoForm } from '../components/investimentos/AtivoForm';
import { GraficoPatrimonio } from '../components/investimentos/GraficoPatrimonio';
import { ResumoCarteira } from '../components/investimentos/ResumoCarteira';
import { Botao, Cartao, EstadoVazio, TituloPagina } from '../components/ui';
import { hojeISO } from '../domain/date';
import { alocacaoPorClasse, criarAtivo, desempenhoCarteira, evolucaoPatrimonio } from '../domain/investimentos';
import { useEstado, useStore } from '../state/store';
import '../components/investimentos/investimentos.css';

export function InvestimentosPage() {
  const store = useStore();
  const { investimentos: ativos } = useEstado();
  const [criando, setCriando] = useState(false);
  const hoje = hojeISO();
  const evolucao = evolucaoPatrimonio(ativos, hoje);

  return (
    <div>
      <TituloPagina acoes={!criando ? <Botao onClick={() => setCriando(true)}>Novo ativo</Botao> : undefined}>Investimentos</TituloPagina>
      <div className="invest-pagina">
        {criando ? (
          <Cartao titulo="Novo ativo">
            <AtivoForm
              onCancelar={() => setCriando(false)}
              onSalvar={(dados) => {
                const r = store.aplicar((s) => criarAtivo(s, dados));
                if (r.ok) setCriando(false);
                return r;
              }}
            />
          </Cartao>
        ) : null}

        {ativos.length === 0 ? (
          !criando && (
            <EstadoVazio titulo="Nenhum ativo ainda" acao={<Botao onClick={() => setCriando(true)}>Cadastre seu primeiro ativo</Botao>}>
              Registre seus investimentos manualmente, com aportes, resgates e o valor atual, para acompanhar rentabilidade e alocação.
            </EstadoVazio>
          )
        ) : (
          <>
            <ResumoCarteira desempenho={desempenhoCarteira(ativos)} />
            <div className="invest-duas-colunas">
              <AlocacaoCarteira fatias={alocacaoPorClasse(ativos)} />
              {evolucao.length > 0 ? (
                <GraficoPatrimonio dados={evolucao} />
              ) : (
                <Cartao titulo="Evolução do patrimônio">
                  <p className="invest-texto-suave">Registre um aporte para acompanhar a evolução mês a mês.</p>
                </Cartao>
              )}
            </div>
            {ativos.map((a) => (
              <AtivoCard key={a.id} ativo={a} hoje={hoje} />
            ))}
          </>
        )}
      </div>
    </div>
  );
}
import { useState } from 'react';
import { ConfirmDialog } from '../components/ConfirmDialog';
import { RegraForm } from '../components/regras/RegraForm';
import { RegraItem } from '../components/regras/RegraItem';
import { Alerta, Botao, Cartao, CampoSelect, EstadoVazio, TituloPagina } from '../components/ui';
import {
  aplicarRegra,
  alternarRegra,
  criarRegra,
  editarRegra,
  excluirRegra,
  moverRegra,
  transacoesAtingidas,
  type EscopoAplicacao,
} from '../domain/regras';
import type { RegraCategoria, Resultado } from '../domain/types';
import { useEstado, useStore } from '../state/store';
import '../components/regras/regras.css';

type Mensagem = { tipo: 'erro' | 'sucesso'; texto: string };

export function RegrasPage() {
  const store = useStore();
  const estado = useEstado();
  const [escopo, setEscopo] = useState<EscopoAplicacao>('outros');
  const [criando, setCriando] = useState(false);
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [aplicando, setAplicando] = useState<RegraCategoria | null>(null);
  const [excluindo, setExcluindo] = useState<RegraCategoria | null>(null);
  const [mensagem, setMensagem] = useState<Mensagem | null>(null);

  const nomeCategoria = new Map(estado.categorias.map((c) => [c.id, c.nome]));

  /** Aplica a operação e mostra o erro, se houver. */
  const executar = (operacao: Parameters<typeof store.aplicar>[0]): Resultado<void> => {
    const r = store.aplicar(operacao);
    setMensagem(r.ok ? null : { tipo: 'erro', texto: r.erro });
    return r;
  };

  const aplicarExistentes = (regra: RegraCategoria) => {
    let alteradas = 0;
    const r = store.aplicar((s) => {
      const a = aplicarRegra(s, regra.id, escopo);
      if (!a.ok) return a;
      alteradas = a.valor.alteradas;
      return { ok: true, valor: a.valor.estado };
    });
    setMensagem(r.ok ? { tipo: 'sucesso', texto: `${alteradas} ${alteradas === 1 ? 'transação atualizada' : 'transações atualizadas'}.` } : { tipo: 'erro', texto: r.erro });
    setAplicando(null);
  };

  return (
    <div>
      <TituloPagina acoes={!criando ? <Botao onClick={() => { setCriando(true); setEditandoId(null); }}>Nova regra</Botao> : undefined}>Regras</TituloPagina>
      <div className="regras-pagina">
        <p className="regras-intro">
          Regras sugerem a categoria (e tags) de transações importadas. A primeira regra ativa da lista que casar com a descrição vence.
        </p>
        {mensagem ? <Alerta tipo={mensagem.tipo}>{mensagem.texto}</Alerta> : null}

        {criando ? (
          <Cartao titulo="Nova regra">
            <RegraForm
              estado={estado}
              onCancelar={() => setCriando(false)}
              onSalvar={(dados) => {
                const r = store.aplicar((s) => criarRegra(s, dados));
                if (r.ok) {
                  setCriando(false);
                  setMensagem(null);
                }
                return r;
              }}
            />
          </Cartao>
        ) : null}

        {estado.regras.length === 0 ? (
          !criando && (
            <EstadoVazio titulo="Nenhuma regra criada" acao={<Botao onClick={() => setCriando(true)}>Criar a primeira regra</Botao>}>
              Crie regras como &ldquo;descrição contém mercado → Alimentação&rdquo; para categorizar importações automaticamente.
            </EstadoVazio>
          )
        ) : (
          <Cartao
            titulo="Regras em ordem de prioridade"
            acoes={
              <div className="regras-escopo">
                <CampoSelect label="Escopo da pré-visualização e da aplicação" value={escopo} onChange={(e) => setEscopo(e.target.value as EscopoAplicacao)}>
                  <option value="outros">Somente em Outros</option>
                  <option value="todas">Todas as categorias</option>
                </CampoSelect>
              </div>
            }
          >
            <ul className="regras-lista" aria-label="Lista de regras">
              {estado.regras.map((r, i) =>
                editandoId === r.id ? (
                  <li key={r.id} className="regras-item-edicao">
                    <RegraForm
                      estado={estado}
                      inicial={r}
                      onCancelar={() => setEditandoId(null)}
                      onSalvar={(dados) => {
                        const res = store.aplicar((s) => editarRegra(s, r.id, dados));
                        if (res.ok) setEditandoId(null);
                        return res;
                      }}
                    />
                  </li>
                ) : (
                  <RegraItem
                    key={r.id}
                    regra={r}
                    posicao={i + 1}
                    total={estado.regras.length}
                    categoriaNome={nomeCategoria.get(r.categoriaId) ?? 'Categoria removida'}
                    atingidas={transacoesAtingidas(estado, r, escopo).length}
                    onSubir={() => executar((s) => moverRegra(s, r.id, -1))}
                    onDescer={() => executar((s) => moverRegra(s, r.id, 1))}
                    onAlternar={() => executar((s) => alternarRegra(s, r.id, !r.ativa))}
                    onEditar={() => { setEditandoId(r.id); setCriando(false); }}
                    onExcluir={() => setExcluindo(r)}
                    onAplicar={() => setAplicando(r)}
                  />
                ),
              )}
            </ul>
          </Cartao>
        )}
      </div>

      {aplicando ? (
        <ConfirmDialog
          titulo="Aplicar regra às transações existentes?"
          mensagem={`${transacoesAtingidas(estado, aplicando, escopo).length} transações (${escopo === 'outros' ? 'somente as que estão em Outros' : 'de todas as categorias'}) terão a categoria trocada para ${nomeCategoria.get(aplicando.categoriaId) ?? ''}${aplicando.tags.length > 0 ? ' e receberão as tags da regra' : ''}. Esta ação não pode ser desfeita.`}
          rotuloConfirmar="Aplicar"
          onCancelar={() => setAplicando(null)}
          onConfirmar={() => aplicarExistentes(aplicando)}
        />
      ) : null}
      {excluindo ? (
        <ConfirmDialog
          titulo="Excluir regra?"
          mensagem={`Excluir a regra "${excluindo.padrao}"? As transações já categorizadas por ela não mudam.`}
          rotuloConfirmar="Excluir"
          perigo
          onCancelar={() => setExcluindo(null)}
          onConfirmar={() => {
            executar((s) => excluirRegra(s, excluindo.id));
            setExcluindo(null);
          }}
        />
      ) : null}
    </div>
  );
}
